/** @param {number[]} values @param {number} index */ function read(values, index) { return values[index]; }
/** @param {number[]} values @param {number} index */ function add(values, index) { return values[index] + 1; }
/** @param {number[]} values @param {number} index */ function absent(values, index) { return values[index] === undefined; }
/** @param {number[]} values @param {number} index */ function kind(values, index) { return typeof values[index]; }
/** @param {number[]} values @param {number} index */ function text(values, index) { return 'value=' + values[index]; }
/** @param {number[]} values @param {number} index */ function fallback(values, index) { return values[index] || 7; }
console.log(read([2], 9));
console.log(add([2], 9));
console.log(absent([2], 9));
console.log(kind([2], 9));
console.log(text([2], 9));
console.log(fallback([0], 0));
console.log(read([2], 0));

function read(values, index) { return values[index]; }
function absent(values, index) { return values[index] === undefined; }
function nil(values, index) { return values[index] === null; }
function add(values, index) { return values[index] + 1; }
console.log(read([null, 4], 0));
console.log(absent([null, 4], 0));
console.log(nil([null, 4], 0));
console.log(nil([null, 4], 9));
console.log(add([null, 4], 0));
console.log(add([null, 4], 9));
